const defs=[['id','Measurement key','text'],['pointId','Point / collar ID','text'],['occurrence','Measurement occurrence','number'],['site','Site / collar','text'],['project','Project','text'],['fieldStart','Field measurement start (local time)','text'],['fieldEnd','Field-sheet end (optional)','text'],['start','.data sample window start','text'],['end','.data sample window end','text'],['mixing','Exclude initial seconds','number'],['temperature','Chamber air (°C)','number'],['pressure','Absolute pressure (kPa)','number'],['chamber','Chamber headspace (L)','number'],['collar','Exposed collar headspace (L)','number'],['loop','Tubing / loop volume (L)','number'],['area','Soil surface area (m²)','number'],['latitude','Latitude (decimal degrees)','number'],['longitude','Longitude (decimal degrees)','number']];
