let workspaceDB;function openWorkspace(){if(!workspaceDB)workspaceDB=new Promise((resolve,reject)=>{const req=indexedDB.open('fieldflux-workspace',1);req.onupgradeneeded=()=>req.result.createObjectStore('workspace');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});return workspaceDB}
async function save(){const snapshot={data,readings,selected,fileName,geometry,recordings,projects,activeProject};try{const db=await openWorkspace();await new Promise((resolve,reject)=>{const tx=db.transaction('workspace','readwrite');tx.objectStore('workspace').put(snapshot,'current');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});return true;}catch(e){$('status').textContent='Workspace could not be saved in this browser. Keep this tab open and export your results before closing.';return false;}}
function blankGeometry(){return{chamber:'',collar:0,loop:0,area:''}}
function ensureProjects(){for(const name of new Set(readings.map(r=>r.project||'Field campaign'))){if(!projects.some(p=>p.name===name))projects.push({name,geometry:blankGeometry()})}if(!projects.length)projects.push({name:'Field campaign',geometry:{...geometry}});for(const rec of recordings)if(!rec.project)rec.project=readings.find(r=>r.sourceId===rec.id)?.project||'Field campaign'}
function projectReadings(){return activeProject?readings.filter(r=>r.project===activeProject):readings}
function projectRecordings(){return activeProject?recordings.filter(rec=>rec.project===activeProject||readings.some(r=>r.sourceId===rec.id&&r.project===activeProject)):recordings}
function syncProjectControls(){ensureOccurrences();ensureProjects();const options='<option value="">All projects</option>'+projects.map(p=>`<option>${esc(p.name)}</option>`).join('');for(const id of ['projectPicker','projectFilter']){$(id).innerHTML=options;$(id).value=activeProject}$('projectContext').textContent=activeProject?`Active project: ${activeProject}. New recordings and readings are added here.`:'Viewing all projects. Select a project before adding recordings or applying chamber setup.';$('applyGeometry').disabled=!activeProject}
function switchProject(name){ensureProjects();if(name&&!projects.some(p=>p.name===name))throw Error('Project not found.');const previous=projects.find(p=>p.name===activeProject);if(previous)previous.geometry={...geometry};activeProject=name;loadGPSTrackControls();geometry={...(projects.find(p=>p.name===name)?.geometry||blankGeometry())};$('recordingFilter').value='';$('siteFilter').value='';selected=readings.findIndex(r=>!name||r.project===name);for(const k of ['chamber','collar','loop','area'])$('g_'+k).value=geometry[k]??'';syncProjectControls();populate();save()}
function createProject(name,copyGeometry=false){name=String(name||'').trim();if(!name)throw Error('Enter a project name.');if(name.length>100)throw Error('Use a project name of 100 characters or fewer.');ensureProjects();if(projects.some(p=>p.name.toLowerCase()===name.toLowerCase()))throw Error('A project with this name already exists. Select it from the project menu.');const next={name,geometry:copyGeometry?{...geometry}:blankGeometry()};projects.push(next);switchProject(name);$('status').textContent=`Created project “${name}”. Upload recordings to start; existing projects are preserved.`;return next}
let dataActionBusy=false;
function renderGasUploadSummary(){const records=projectRecordings(),count=records.length;$('gasUploadCount').textContent=`${count} ${count===1?'file':'files'} uploaded${activeProject?' to this project':' across all projects'}`;$('gasUploadNames').textContent=count?records.slice(0,3).map(rec=>rec.name).join(' · ')+(count>3?' · +'+(count-3)+' more':''):'No recordings uploaded yet.';$('gasUploadNames').title=records.map(rec=>rec.name).join('\n');$('gasUpload').textContent=count?'Add more recordings':'Add gas recordings'}
function renderOtherUploadSummary(kind){const gps=kind==='gps',prefix=gps?'gps':'meta',nameKey=gps?'gpsUploadName':'conditionsUploadName',rows=projectReadings(),covered=rows.filter(r=>gps?hasGPS(r):r.conditionsUploaded),files=new Map();for(const row of covered)if(row[nameKey])files.set(JSON.stringify([row.project,row[nameKey]]),{name:row[nameKey],project:row.project});if(gps)for(const project of projects.filter(p=>!activeProject||p.name===activeProject))for(const track of project.gpsTracks||[])files.set(JSON.stringify([project.name,track.name]),{name:track.name,project:project.name});const names=[...files.values()],legacy=covered.filter(r=>!r[nameKey]).length;$(prefix+'UploadCount').textContent=names.length?`${names.length} ${names.length===1?'file':'files'} uploaded${activeProject?' to this project':' across all projects'}`:covered.length?(gps?'GPS data present':'Field conditions present'):'0 files uploaded';const descriptions=names.map(file=>activeProject?file.name:file.project+': '+file.name);$(prefix+'UploadNames').textContent=descriptions.length?descriptions.slice(0,3).join(' · ')+(descriptions.length>3?' · +'+(descriptions.length-3)+' more':'')+(legacy?' · '+legacy+' earlier/manual reading(s), filename unavailable':''):covered.length?`${covered.length} reading(s) have data; original filename was not saved by the earlier version.`:'No '+(gps?'GPS':'field-condition')+' files uploaded yet.';$(prefix+'UploadNames').title=descriptions.join('\n');$(prefix+'Upload').textContent=covered.length?(gps?'Add / replace GPS locations':'Add / replace field conditions'):(gps?'Browse GPS locations':'Browse field conditions');}
function renderAllUploadSummaries(){renderGasUploadSummary();renderOtherUploadSummary('meta');renderOtherUploadSummary('gps')}
function renderDataManager(){renderAllUploadSummaries();renderGPSTrackReport();const records=activeProject?projectRecordings():[];$('uploadedFiles').innerHTML=!activeProject?'<p class="muted">Select a project to manage its uploaded data.</p>':!records.length?'<p class="muted">No recordings uploaded to this project yet.</p>':records.map(rec=>{const count=readings.filter(r=>r.sourceId===rec.id&&r.project===activeProject).length;return`<div class="uploaded-file"><div><strong>${esc(rec.name)}</strong><br><span class="muted">${(rec.count||0).toLocaleString()} samples · ${count} project reading(s)</span></div><button type="button" class="danger-button" data-remove-source="${esc(rec.id)}" ${dataActionBusy?'disabled':''}>Remove file</button></div>`}).join('');$('uploadedFiles').querySelectorAll('[data-remove-source]').forEach(button=>button.onclick=()=>runDataAction(()=>removeUploadedRecording(button.dataset.removeSource)));const disabled=!activeProject||dataActionBusy;for(const id of ['clearConditions','clearGPS','clearProjectData'])$(id).disabled=disabled;$('dataManagerNote').textContent=activeProject?'Clear field conditions removes this project’s temperatures, pressures and field-time notes. Clear GPS removes its coordinates. Clear project data removes its recordings and readings but keeps the project name and chamber setup. Other projects are preserved.':'Data removal is scoped to one active project.';}
