async function persistDataAction(message){$('recordingFilter').value='';$('siteFilter').value='';selected=readings.findIndex(r=>r.project===activeProject);recomputeProjectGPS(activeProject);populate();const ok=await save();if(ok!==false){try{localStorage.removeItem('fieldflux-v1')}catch(e){}$('status').textContent=message}return ok;}
