async function runDataAction(action){if(dataActionBusy)return;dataActionBusy=true;renderDataManager();try{await action()}catch(error){$('status').textContent='Could not clear data: '+error.message}finally{dataActionBusy=false;renderDataManager()}}
function sourceRecords(r){if(!r?.sourceId)return data;if(sourceRecords.ref!==data){sourceRecords.ref=data;sourceRecords.index=new Map();for(const p of data){if(!sourceRecords.index.has(p.sourceId))sourceRecords.index.set(p.sourceId,[]);sourceRecords.index.get(p.sourceId).push(p)}}return sourceRecords.index.get(r.sourceId)||[]}
function stamp(s){return Date.parse(String(s).trim().replace(' ','T')+'Z')/1000} // nominal file-local times; never use browser timezone
