function newReading(){if(!activeProject){alert('Select or create a project first.');return}let n=readings.length+1;while(projectReadings().some(r=>r.id==='R'+String(n).padStart(3,'0')))n++;const source=projectRecordings().find(x=>x.id===$('recordingFilter').value)||projectRecordings()[0];if(!source){alert('Upload a gas recording first.');return}readings.push({sourceId:source.id,sourceFile:source.name,id:'R'+String(n).padStart(3,'0'),site:'',project:activeProject,start:'',end:'',mixing:0,temperature:'',pressure:'',...geometry,latitude:'',longitude:''});selected=readings.length-1;populate();save()}
function readingChart(){const r=current();if(!r||!data.length){$('chart').innerHTML='<text x="300" y="120" text-anchor="middle" fill="#217A8A">No reading selected in this project</text>';$('chartSub').textContent='Upload a recording or select a reading to inspect its concentration.';return;}const e=evaluate(r),a=stamp(r.start),b=stamp(r.end),points=sourceRecords(r).filter(x=>x.t>=a&&x.t<=b&&Number.isFinite(x[gas]));if(points.length<2){$('chart').innerHTML='<text x="300" y="120" text-anchor="middle" fill="#64748B">No valid data in this interval</text>';return}const lo=Math.min(...points.map(p=>p[gas])),hi=Math.max(...points.map(p=>p[gas])),span=hi-lo||1,x=t=>55+(t-a)/(b-a)*525,y=v=>195-(v-lo)/span*155;let html='';for(let i=0;i<5;i++){let v=lo+i*span/4;html+=`<line x1="55" x2="580" y1="${y(v)}" y2="${y(v)}" stroke="#e7ebe3"/><text x="45" y="${y(v)+4}" text-anchor="end" font-size="10" fill="#64748B">${v.toFixed(1)}</text>`}const skip=Math.max(1,Math.floor(points.length/1000));html+=`<polyline fill="none" stroke="${gas==='co2'?'#217A8A':'#C06131'}" stroke-width="1.8" points="${points.filter((_,i)=>i%skip===0).map(p=>x(p.t)+','+y(p[gas])).join(' ')}"/>`;const f=gas==='co2'?e.c:e.h;if(f)html+=`<line x1="${x(f.min)}" x2="${x(f.max)}" y1="${y(f.intercept+f.slope*(f.min-f.t0))}" y2="${y(f.intercept+f.slope*(f.max-f.t0))}" stroke="#283b35" stroke-dasharray="5 4"/>`;for(let i=0;i<5;i++)html+=`<text x="${55+525*i/4}" y="218" text-anchor="middle" font-size="10" fill="#64748B">${Math.round((b-a)*i/4)} s</text>`;html+=`<text x="55" y="17" fill="#64748B" font-size="11">${gas==='co2'?'CO₂ · ppm':'CH₄ · ppb'}</text>`;$('chart').innerHTML=html;$('chartSub').textContent=`${r.id} · ${points.length.toLocaleString()} valid ${gas.toUpperCase()} samples`;}
