function overviewData(g){const all=filtered().map(r=>({r,e:evaluate(r)})),valid=all.filter(p=>Number.isFinite(p.e[g])),values=valid.map(p=>p.e[g]).sort((a,b)=>a-b);return{all,valid,mean:values.length?values.reduce((a,b)=>a+b,0)/values.length:null,median:values.length?(values[Math.floor((values.length-1)/2)]+values[Math.ceil((values.length-1)/2)])/2:null}}
