 for(let i=0;i<5;i++){const v=minV+(maxV-minV)*i/4;html+=`<line x1="85" x2="870" y1="${y(v)}" y2="${y(v)}" stroke="#ddd8cf"/><text x="76" y="${y(v)+4}" fill="#217A8A" font-size="10" text-anchor="end">${num(v)}</text>`;const t=minT+(maxT-minT)*i/4,iso=new Date(t*1000).toISOString();html+=`<text x="${85+785*i/4}" y="251" font-size="10" text-anchor="middle" fill="#172033">${iso.slice(0,10)}</text><text x="${85+785*i/4}" y="267" font-size="10" text-anchor="middle" fill="#217A8A">${iso.slice(11,16)}</text>`}
