function summaryMetrics(rows){const results=rows.map(r=>({r,e:evaluate(r)}));const med=xs=>{xs=xs.filter(Number.isFinite).sort((a,b)=>a-b);return xs.length?(xs[Math.floor((xs.length-1)/2)]+xs[Math.ceil((xs.length-1)/2)])/2:null};const perGas=(g,fit)=>{const valid=results.filter(p=>Number.isFinite(p.e[g]));return{mean:valid.length?valid.reduce((sum,p)=>sum+p.e[g],0)/valid.length:null,n:valid.length,r2:med(valid.map(p=>p.e[fit]?.r2)),r2n:valid.filter(p=>Number.isFinite(p.e[fit]?.r2)).length}};return{co2:perGas('co2','c'),ch4:perGas('ch4','h'),total:rows.length,complete:results.filter(p=>Number.isFinite(p.e.co2)&&Number.isFinite(p.e.ch4)).length,provisional:results.filter(p=>Number.isFinite(p.e.co2)&&Number.isFinite(p.e.ch4)&&!p.r.reviewed&&(p.r.boundarySource==='remark'||p.r.conditionsUploaded)).length}}
function renderMetricCards(){const single=$('chartView').value==='single',r=current(),e=r?evaluate(r):null,summary=summaryMetrics(single?(r?[r]:[]):filtered());$('co2StatLabel').textContent=single?'CO₂ flux · selected reading':'Mean CO₂ flux';$('ch4StatLabel').textContent=single?'CH₄ flux · selected reading':'Mean CH₄ flux';$('co2Stat').textContent=num(single?e?.co2:summary.co2.mean);$('ch4Stat').textContent=num(single?e?.ch4:summary.ch4.mean);$('co2StatNote').textContent=single?(r?'Reading '+r.id:'No reading selected'):summary.co2.n+' calculated readings';$('ch4StatNote').textContent=single?(r?'Reading '+r.id:'No reading selected'):summary.ch4.n+' calculated readings';$('fitStatLabel').textContent=single?'R² · CO₂ / CH₄':'Median R² · CO₂ / CH₄';$('fitStat').textContent=num(single?e?.c?.r2:summary.co2.r2)+' / '+num(single?e?.h?.r2:summary.ch4.r2);$('fitStatNote').textContent=single?'Selected closure fit window':`Reading-fit medians · n=${summary.co2.r2n} / ${summary.ch4.r2n}`;$('countStatLabel').textContent=single?'Reading in current view':'Readings in filtered view';$('countStat').textContent=summary.total;$('sampleStat').textContent=`${summary.complete} calculated · ${summary.provisional} provisional`;$('metricScope').textContent=single?`Cards show the selected reading${r?' '+r.id:''}. Switch to a flux time-series view for the filtered campaign summary.`:'Cards summarize the current project, recording and site/collar filters. Flux is the equal-weight mean of calculated reading fluxes; R² is the median of their individual fit values, not a pooled regression. Incomplete readings are excluded from statistics; complete provisional readings are included. Hourly/daily chart grouping does not reweight these reading-level statistics.';}
