 const traces=filtered().map((r,i)=>{const a=stamp(r.start),b=stamp(r.end);return{r,a,b,colour:traceColours[i%traceColours.length],p:sourceRecords(r).filter(p=>p.t>=a&&p.t<=b&&Number.isFinite(p[gas]))}}).filter(t=>Number.isFinite(t.a)&&t.b>t.a&&t.p.length>1);
