 let min=Infinity,max=-Infinity,minT=Infinity,maxT=-Infinity;for(const trace of traces)for(const p of trace.p){min=Math.min(min,p[gas]);max=Math.max(max,p[gas]);const t=mode==='timeline'?p.t:p.t-trace.a;minT=Math.min(minT,t);maxT=Math.max(maxT,t)}const range=max-min||1,timeRange=maxT-minT||1,x=t=>58+(t-minT)/timeRange*520,y=v=>190-(v-min)/range*150;let html='';for(let i=0;i<5;i++){const v=min+i*range/4;html+=`<line x1="58" x2="578" y1="${y(v)}" y2="${y(v)}" stroke="#ddd8cf"/><text x="50" y="${y(v)+3}" font-size="9" fill="#217A8A" text-anchor="end">${v.toFixed(1)}</text>`;const t=minT+i*timeRange/4,label=mode==='timeline'?new Date(t*1000).toISOString().slice(5,19).replace('T',' '):Math.round(t)+' s';html+=`<text x="${58+520*i/4}" y="213" font-size="8" fill="#217A8A" text-anchor="middle">${label}</text>`}
